package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamInstrumentsBank2 {
    private const val T = "පංචතූර්ය නාද වර්ගීකරණය හා නර්තන වාද්‍ය භාණ්ඩ"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ගැටබෙරයේ දකුණු ඇස සහ වම් ඇස වෙනස් විෂ්කම්භයන්ගෙන් හා වෙනස් සම්වලින් සකසා ඇත්තේ ඇයි?", "තියුණු හා ගැඹුරු යන නාද දෙකම ලබා ගැනීමට", "කඳ සඳහා තෝරා ගත් ලී ප්‍රමාණය මදි වූ නිසා", "සාම්ප්‍රදායික ක්‍රමය වැරදීමකින් කපන ලද නිසා", "බෙරයේ මුළු බර සැහැල්ලු කර ගැනීම සඳහා පමණි", "වඳුරු සමින් තියුණු නාදයත් හරක් සමින් ගැඹුරු නාදයත් උපදී."),
        q("පංචතූර්ය නාද වර්ගීකරණය අනුව 'තම්මැට්ටම' අයත් වන්නේ කුමන ගණයටද?", "විතත ගණයට", "ආතත ගණයට", "ඝන ගණයට", "සුසිර ගණයට", "කඩිප්පු යුගලයෙන්ම පමණක් ගසා වාදනය කරන නිසා තම්මැට්ටම විතත වාද්‍ය භාණ්ඩයකි."),
        q("සබරගමු 'දිගු දවුල' පංචතූර්ය නාද වර්ගීකරණය යටතේ වර්ග කරනු ලබන්නේ කුමන ගණයටද?", "විතතාතත ගණයට", "සුසිර ගණයට", "ඝන ගණයට", "ආතත ගණයට", "අත සහ කඩිප්පුව යන දෙකම වාදනයට යොදා ගන්නා බැවින් විතතාතත නම් වේ."),
        q("'හොරණෑව' නිර්මාණය කිරීමේදී යොදාගන්නා ප්‍රධාන කොටස් තුන මොනවාද?", "තල්පත් පීප්පය, ලී බඳ සහ පිත්තල කෝණය", "හරක් සම, වඳුරු සම සහ කඩිප්පුව", "මැටි කළය, වරපටිය සහ සිළම්බු", "පිත්තල පෙති, රාමුව සහ පබළු", "මුවින් පිඹින තල්පත් පත්‍රය සිදුරු ඇති ලී නලයට සවි කර පිත්තල අගින් හඬ විහිදුවයි."),
        q("පහතරට 'යක් බෙරය' වාදනය කරන විට වාදකයා බෙරයේ දෙපස ඇස් දෙකටම පහර දෙන්නේ කුමකින්ද?", "දෙඅත්වල අල්ල හා ඇඟිලිවලින් පමණි", "කඩිප්පු දෙකකින්", "පාදයෙන්", "ලී කෝටුවකින් හා අතින්", "දෙඅතින්ම වයන බැවින් යක් බෙරය ආතත වාද්‍ය භාණ්ඩ ගණයට අයත් වේ."),
        q("'උඩැක්කිය' හා 'ඩමරුව' අතර ඇති ප්‍රධාන සමානකම කුමක්ද?", "මැදින් සිහින් වූ දෙපස හම් ගැසූ වැලි හෝරා හැඩැති භාණ්ඩ වීම", "දෙකම මුවින් පිඹින සුසිර වාද්‍ය භාණ්ඩ වීම", "දෙකම පිත්තල ලෝහ තැටි යුගලයන් වීම", "දෙකම බිම තබා කඩිප්පු යුගලයෙන් වැයීම", "ශිව දෙවියන්ගේ ඩමරුවේ ආභාසය උඩැක්කියට ලැබී ඇති බව සැලකේ."),
        q("උඩැක්කියේ දෙපස හම් සකස් කිරීම සඳහා බහුලව යොදාගන්නා සියුම් සත්ව සම කුමක්ද?", "තලගොයි සම හෝ එළු සම", "මී හරක් සම", "අලි සම", "කිඹුල් සම", "කුඩා උඩැක්කියෙන් මෘදු හා පැහැදිලි හඬක් ලබා ගැනීමට තුනී සම් යොදයි."),
        q("'බුම්මැඩිය' වැඩි වශයෙන්ම භාවිත වන්නේ කුමන ජන කලා අංගයන්හිද?", "ගොයම් කවි, රබන් හා ගැමි ජන නැටුම් පසුබිම් වාදනයේදී", "පහතරට සන්නි යකුමේදී", "කොහොඹා කංකාරියේදී", "සොකරි රංගනයේදී පමණක්", "කමතේ ගොයම් නෙළන අවස්ථාවලදී හා ගැමි උත්සවවලදී බුම්මැඩිය මනරම් රිද්මයක් දෙයි."),
        q("'තාලම්පට' යුගලයේ තැටි දෙක එකට සම්බන්ධ කර ඇත්තේ කුමක් මගින්ද?", "මැද සිදුරු තුළින් යැවූ කපු නූල් හෝ රෙදි පටියකින්", "යකඩ දම්වැලකින්", "ප්ලාස්ටික් කූරකින්", "මැලියම්වලින්", "අල්ලා ගැනීමට පහසු වන සේ හා හඬ අවහිර නොවන සේ මැදින් ලණුවක් දමා ගැටගසයි."),
        q("තාලම්පට වාදනයේදී 'තද කළ කෙටි නාදය' (තිත්) උපදවන්නේ කෙසේද?", "තැටි දෙක එකට ගසා මොහොතක් ඇලවී තැබීමෙන්", "තැටි දෙක ගැසූ වහාම ඈත් කිරීමෙන්", "එක් තැටියක් පමණක් බිම දැමීමෙන්", "තැටියට පිඹීමෙන්", "කම්පනය ක්ෂණිකව නතර කළ විට කෙටි තිත් හඬත්, ඈත් කළ විට දිගු තා හඬත් ඇසේ."),
        q("'හක්ගෙඩිය' සාමාන්‍යයෙන් කුමන ස්වාභාවික මූලාශ්‍රයකින් ලබා ගන්නා වාද්‍ය භාණ්ඩයක්ද?", "මුහුදේ ජීවත් වන විශාල බෙල්ලෙකුගේ කවචයකින්", "ගසක කඳකින්", "මැටි පිළිස්සීමෙන්", "පිත්තල උණු කිරීමෙන්", "මංගල වස්තුවක් ලෙස සලකන දක්ෂිණාවෘත හෝ සාමාන්‍ය හක්ගෙඩි පිඹිනු ලැබේ."),
        q("'කොම්බුව' නමැති වාද්‍ය භාණ්ඩය බොහෝ විට පිඹිනු ලබන්නේ කුමන අවස්ථාවලදීද?", "දේවාල තේවා, පෙරහැර හා රාජකීය උත්සවවලදී", "නැළවිලි ගී ගැයීමේදී", "පාසල් පන්ති කාමර තුළ", "නිහඬ භාවනා අවස්ථාවේදී", "දිගු ඈතකට ඇසෙන ගාම්භීර හඬක් කොම්බුවෙන් පිට වේ."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතර 'බංකු රබානේ' රාමුව සාදා ඇති ප්‍රධාන දැව වර්ග මොනවාද?", "කොස් හෝ කොහොඹ දැව", "කෙසෙල් කඳ", "පිදුරු", "උණ කෝටු", "වටකුරු විශාල රාමුව මත එළු හෝ ගව සම තදින් ගසා බංකු රබාන තනයි."),
        q("ගැටබෙරයේ 'මැද පුම්බා ඇති' කොටසේ සිට දෙකෙළවර දක්වා ඇති අභ්‍යන්තර කුහරය කුමක් සඳහා උපකාරී වේද?", "ශබ්දය ඇතුළත දෝංකාර දී ප්‍රබල අනුනාදයක් ඇති කිරීමට", "වතුර ගබඩා කිරීමට", "කඩදාසි දැමීමට", "බෙරයේ බර වැඩි කිරීමට", "ලීය ඇතුළතින් හාරා ඇති ප්‍රමාණය අනුව බෙරයේ හඬෙහි ගුණාත්මක බව තීරණය වේ."),
        q("දේශීය හේවිසි වාදනයේදී 'පෝය හේවිසි' සහ 'අලුත් අවුරුදු හේවිසි' අතර වෙනස කුමක්ද?", "අවස්ථාව අනුව වාදනය කරන පද රටා සහ ලය වෙනස් වීම", "වෙනස් විදේශීය බෙර භාවිත කිරීම", "හොරණෑව නොපිඹීම", "පාවහන් පැළඳ වැයීම", "අවමංගල්‍ය මළ බෙර හා මංගල හේවිසි එකිනෙකට වෙනස් රිද්මයන්ගෙන් වැයේ."),
        q("සම්ප්‍රදායික බෙරයක හඬ 'බුරුල් වී' පැහැදිලි බව අඩු වූ විට වාදකයා ක්ෂණිකව කරන්නේ කුමක්ද?", "වරපටි තද කිරීම හෝ හම මඳක් රත් කර ගැනීම", "බෙරය වතුරේ දැමීම", "බෙරය කැඩීම", "සම ඉරා දැමීම", "තෙත කාලගුණයේදී හම ලිහිල් වන විට වරපටි ඇදීමෙන් හඬ නිවැරදි කරයි."),
        q("පහතරට යක් බෙරයේ දෙපස ඇස් හඳුන්වනු ලබන්නේ කුමන නම්වලින්ද?", "සුර අත (දකුණ) සහ වම් අත හෙවත් දොං අත", "උඩු ඇස සහ යටි ඇස", "සිංහ ඇස සහ මුව ඇස", "වීදුරු ඇස සහ ලී ඇස", "වම් හා දකුණු අත්වලින් ලබාගන්නා නාද විවිධත්වය යක් බෙරයේ ජවය මවයි."),
        q("උඩරට නැටුමේදී 'පන්තේරුව' වාදනය කිරීමේදී පිත්තල පෙතිවලින් නැඟෙන ශබ්දය හඳුන්වන්නේ කෙසේද?", "ජලං ජලං යන මිහිරි ලෝහමය ඝන නාදය", "ගැඹුරු බෙර හඬ", "හුළං පිඹින හඬ", "බටනලා නාදය", "වළල්ලේ සවි කර ඇති පිත්තල කැබලි යුගලයන් ගැටීමෙන් මෙම හඬ උපදී."),
        q("සිංහල සංස්කෘතියේ 'පංචතූර්ය නාද' අතර 'අවනද්ධ' යන පොදු නාමයෙන් හඳුන්වන්නේ කුමන භාණ්ඩ කාණ්ඩද?", "සම් යොදා සාදන ලද සියලුම බෙර වර්ග (ආතත, විතත, විතතාතත)", "ලෝහ තැටි පමණි", "සුළං පිඹින නළා පමණි", "තන්තු භාණ්ඩ පමණි", "සමකින් වැසුණු බඳක් සහිත වාද්‍ය භාණ්ඩ අවනද්ධ නමින් හැඳින්වේ."),
        q("දිගු දවුලේ වම් අතින් පමණක් ගැසීමේදී ලැබෙන නාදය හා දකුණු අතේ කඩිප්පුවෙන් ගැසීමේදී ලැබෙන නාදය කෙබඳුද?", "වම් අතින් මෘදු ගැඹුරු නාදයත් කඩිප්පුවෙන් තියුණු හඬත් ලැබේ", "දෙපසින්ම එකම තියුණු ස්වර හඬක් ලැබේ", "හම ඝන නිසා පැහැදිලි ශබ්දයක් නොලැබේ", "දෙපසින්ම සුසිර නළා නාදයක් පමණක් ලැබේ", "අතේ සහ කඩිප්පුවේ හඬ සංයෝජනය දවුලේ විශේෂත්වයකි."),
        q("බටනලාව නමැති සුසිර වාද්‍ය භාණ්ඩය නිපදවා ඇත්තේ කුමන ස්වාභාවික ශාක කොටසකින්ද?", "සිහින් උණ බට හෙවත් බට ලීයෙන්", "පොල් කටුවකින්", "වෙල් කදුරු කොටයකින්", "කොස් ලී පුවරුවකින්", "ගොපලු වෙස් ගත් චරිත හා ජන සංගීතය සමඟ බටනලාව බැඳී පවතී."),
        q("උඩරට නර්තන වාද්‍ය භාණ්ඩයක් වන 'රබාන' විශේෂයෙන්ම කාන්තා නැටුම්වල ජනප්‍රිය වීමට හේතුව කුමක්ද?", "සැහැල්ලු බව, අලංකාර වටකුරු හැඩය හා හැසිරවීමේ පහසුව", "ඉතා බර වීම", "කඩිප්පු හතරක් අවශ්‍ය වීම", "මුවින් පිඹීමට හැකි වීම", "එක් අතකින් කරකවමින් අලංකාර රංගනයක් දීමට අත් රබාන පහසුය."),
        q("පහතරට 'මිණි ගෙඩිය' හෝ 'ගෙජ්ජි' වල ඇතුළත ශබ්දය උපදවන කුඩා ගෝලය සාදා ඇත්තේ කුමකින්ද?", "කුඩා යකඩ හෝ පිත්තල ඇටයකින්", "මැටි කැබැල්ලකින්", "පුළුන් කැබැල්ලකින්", "වීදුරු කැබැල්ලකින්", "ලෝහ කුහරය තුළ කුඩා ලෝහ ඇටය ගැටීමෙන් පැහැදිලි සීනු හඬක් නැඟේ."),
        q("පැරණි ලංකාවේ 'රණ බෙර' හා 'මළ බෙර' යන අවස්ථා දෙකේදී බෙර වාදනය වෙනස් වන්නේ කුමකින්ද?", "වාදන පද රටා, ලය හා ගෞරව චාරිත්‍ර අනුව", "බෙරයේ වර්ණය අනුව පමණි", "රණ බෙරය ජලයේ තබා වැයීමෙන්", "මළ බෙරය තාලම්පටකින් වැයීමෙන්", "විවිධ සමාජ අවස්ථාවලදී බෙර වාදනය භාවිත කළ ආකාරය සම්ප්‍රදායෙන් නියම වී තිබේ."),
        q("වාද්‍ය භාණ්ඩයක් වන 'ගැටබෙරයේ' හම තද කිරීමට යොදන වරපටිය සාදන්නේ කුමන සත්ව හමකින්ද?", "ගව හමෙන් (හරක් සමෙන්)", "වඳුරු සමෙන්", "සමනල තටුවලින්", "කපු නූලෙන්", "ශක්තිමත් බව හා ඇදීමේ ප්‍රතිරෝධය නිසා ගව සමෙන් වරපටි කපා ගනී."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතර 'තම්මැට්ටම' වැඩි වශයෙන්ම වාදනය කරන්නේ කුමන ශාන්තිකර්ම හා පූජා අවස්ථාවලදීද?", "විහාර තේවා, ඇසළ පෙරහැර හා සබරගමු පහන් මඩුවල", "කළගෙඩි නැටුමේදී පමණි", "ගොයම් කැපීමේදී පමණි", "බැලේ නැටුමේදී", "දවුල සමඟ එක්ව හේවිසි වාදනයේ අත්‍යවශ්‍ය අංගයක් ලෙස තම්මැට්ටම වයයි."),
        q("ගැටබෙරයේ 'කුරලය' යනුවෙන් හඳුන්වන්නේ බෙරයේ කුමන කොටසක්ද?", "බෙර හම කෙළවර වටා ගෙතූ වළල්ල හා බැම්ම", "බෙරයේ මැද ලී කඳ", "කඩිප්පුවේ අග කොටස", "වරපටියේ මැද", "වෙණිවැල් වටා හම් පටි ගොතා ශක්තිමත් කුරලය නිමවා ඇත."),
        q("පහතරට 'යක් බෙරය' වාදනය කිරීමේදී නැට්ටුවා සහ වාදකයා අතර සිදුවන 'අත්පද හුවමාරුව' වැදගත් වන්නේ ඇයි?", "රංගනයේ ජවය හා සජීවී නාට්‍යමය බව වර්ධනය කිරීමට", "බෙරය විවේක ගැන්වීමට", "ප්‍රේක්ෂකයන් නැඟිටුවීමට", "හොරණෑව පිරිසිදු කිරීමට", "නැට්ටුවා හා බෙරකරු එකිනෙකාට අභියෝග කරමින් රිද්ම රටා මවති."),
        q("ශ්‍රී ලංකාවේ සම්ප්‍රදායික වාද්‍ය භාණ්ඩ නිපදවන ශිල්පීන් 'ගැටබෙර' කඳ සකස් කිරීමේදී ලීය වියළා ගන්නේ ඇයි?", "පසු කාලීනව පැලීම වළක්වා පැහැදිලි හඬක් ලබා ගැනීමට", "බෙර කඳ ඉක්මනින් දිරා යාම පහසු කිරීමට", "ලීයේ බර දෙගුණයකින් වැඩි කර ගැනීමට", "බෙර හම වරපටිවලින් තොරව ඇලවීම සඳහා", "හොඳින් පදම් කළ දැව වලින් සෑදූ බෙරය පරම්පරා ගණනාවක් භාවිත කළ හැකිය."),
        q("උඩැක්කියේ බඳ මැදින් සිහින්ව තනා තිබීමෙන් වාදකයාට ලැබෙන ප්‍රායෝගික පහසුව කුමක්ද?", "තනි අතින් අල්ලා මැද පටිය තද කිරීමට හැකි වීම", "දෙපා මැද රඳවා කඩිප්පුවෙන් ගැසීමට හැකි වීම", "වෙස් තට්ටුව මත ආරක්ෂිතව පැළඳීමට හැකි වීම", "මුවින් පිඹින සුසිර නාදයක් ලබා ගැනීමට හැකි වීම", "උඩැක්කියේ හැඩය වාදනයේදී හඬ වෙනස් කිරීමට සුවිශේෂී ලෙස උපකාරී වේ."),
        q("සිංහල සාම්ප්‍රදායික 'මඟුල් බෙර' වාදනය ආරම්භ කිරීමට පෙර බෙරකරු සිත තබා ගන්නා පිළිවෙත කුමක්ද?", "තෙරුවන් ගුණ සිහි කර ශුභ වාදනයක් ලෙස ගෞරවයෙන් වැයීම", "ඉක්මනින් වයා අවසන් කර දුව යාම", "නින්දෙන් වාදනය කිරීම", "කතා කරමින් වැයීම", "පූජනීය ගෞරවයෙන් යුතුව මඟුල් බෙර වාදනය සිදු කිරීම චාරිත්‍රයකි."),
        q("පංචතූර්ය වර්ගීකරණය අනුව 'සුසිර' ගණයට අයත් නොවන වාද්‍ය භාණ්ඩය තෝරන්න.", "තාලම්පට", "හොරණෑව", "බටනලාව", "හක්ගෙඩිය", "තාලම්පට ලෝහ තැටි දෙකක් ගැටීමෙන් වයන ඝන වාද්‍ය භාණ්ඩයකි."),
        q("පහතරට නර්තන වාද්‍ය භාණ්ඩ අතරින් 'තම්මැට්ටම' හා සමානව කඩිප්පු දෙකකින් නොව තනි කඩිප්පුවකින් වයන බෙරය කුමක්ද?", "දවුල", "උඩැක්කිය", "ගැටබෙරය", "යක් බෙරය", "දවුල වයන්නේ එක් අතක කඩිප්පුවකින් සහ අනෙක් අතේ අල්ලෙනි."),
        q("දේශීය වාද්‍ය භාණ්ඩයක් වන 'රබාන' සාමාන්‍යයෙන් අයත් වන්නේ කුමන බෙර හැඩයටද?", "පැතලි වෘත්තාකාර එක් ඇසක් පමණක් ඇති බෙර හැඩයට", "දෙපසම ඇස් ඇති දිගු නල හැඩයට", "වැලි හෝරා හැඩයට", "ත්‍රිකෝණාකාර හැඩයට", "එක් පැත්තක පමණක් සම ගසා අනෙක් පස විවෘතව තබා රබාන තනයි."),
        q("'හොරණෑව' වාදනය කරන විට වාදකයා නොනවත්වා දීර්ඝ තනුවක් වැයීමට භාවිත කරන ශිල්පීය හුස්ම ක්‍රමය කුමක්ද?", "වෘත්තාකාර ශ්වසනය හෙවත් නාසයෙන් හුස්ම ගනිමින් කම්මුල්වලින් සුළං පිඹීම", "තනුව අතරතුර හුස්ම ගැනීම සම්පූර්ණයෙන් නතර කර පිඹීම", "සෑම තාල පදයකටම පසු මිනිත්තු පහක් නිහඬව විවේක ගැනීම", "කම්මුල් නොපුම්බා කටින් පමණක් කෙටි හුස්ම ගනිමින් පිඹීම", "පළපුරුදු හොරණෑ වාදකයෝ කම්මුල්වල සුළං රඳවා නොනැවතී වාදනය කරති."),
        q("දේශීය නර්තනයට වාද්‍ය භාණ්ඩ මඟින් සැපයෙන ප්‍රධානතම දායකත්වය කුමක්ද?", "නැටුමේ තාලය, ලය හා භාවමය උද්යෝගය නිර්මාණය කිරීම", "නැට්ටුවන්ගේ අත් බැඳ තැබීම", "වේදිකාව අඳුරු කිරීම", "ප්‍රේක්ෂකයන් නිදි කරවීම", "වාදනය නොමැතිව සම්ප්‍රදායික නර්තනයක රිද්මමය ජීව ගුණය මතු නොවේ."),
        q("උඩරට නැටුමේදී 'ගැටබෙර' පද කටපාඩම් කිරීමට ආධුනිකයා ඉගෙන ගන්නා මූලික පාඩම හඳුන්වන්නේ කුමන නමකින්ද?", "හස්ත සරඹ හෙවත් බෙර අත් හුරුව (මඟුල් බෙර පද)", "වෙස්මුහුණු කැපීම", "සිළම්බු ලෑම", "කඩතුරාව ඇදීම", "මූලික බෙර හුරුවෙන් තත්-දොං-තක-තරි නාද නිවැරදිව වැයීමට පුහුණු කෙරේ."),
        q("ශ්‍රී ලංකාවේ පැරණි විහාර චිත්‍රවල දැකිය හැකි 'වීණාව' වැනි තන්තු භාණ්ඩ අයත් වන්නේ කුමන වාද්‍ය වර්ගයටද?", "තත වාද්‍ය භාණ්ඩ ගණයට", "සුසිර ගණයට", "ඝන ගණයට", "අවනද්ධ ගණයට", "තත් කම්පනය කිරීමෙන් මිහිරි නාද උපදවන භාණ්ඩ තත ගණයට වැටේ."),
        q("පහතරට 'යක් බෙරය' වාදනය කිරීමෙන් පසු බෙර හමට වැඩි ආරක්ෂාවක් ලැබෙන පරිදි තැබිය යුත්තේ කෙසේද?", "වියළි ස්ථානයක ආවරණය කර ආරක්ෂිත රාක්කයක", "තෙත් බිමක", "තද අව්වේ දින ගණනක්", "බර පෙට්ටිවලට යට කර", "ස්වාභාවික සම් හා දැව ආරක්ෂා කිරීමට නිසි නඩත්තුව අත්‍යවශ්‍ය වේ."),
        q("'පන්තේරුව' සහ 'තාලම්පට' යන වාද්‍ය භාණ්ඩ දෙකෙහි ඇති ප්‍රධාන පොදු ලක්ෂණය කුමක්ද?", "දෙකම පිත්තල ලෝහයෙන් සැකසූ ඝන වාද්‍ය භාණ්ඩ වීම", "දෙකම සම් ගැසූ බෙර වීම", "දෙකම මුවින් පිඹින නළා වීම", "දෙකම මැටියෙන් තැනීම", "ලෝහ කොටස් ගැටීමෙන් රිද්ම නාද ඉපදීම මෙම භාණ්ඩ දෙකේම පොදු ලක්ෂණයයි."),
        q("දේශීය නර්තන වාද්‍ය භාණ්ඩ අතර 'කඩිප්පුව' භාවිත කරන භාණ්ඩ යුගලය තෝරන්න.", "දවුල සහ තම්මැට්ටම", "උඩැක්කිය සහ රබාන", "ගැටබෙරය සහ යක් බෙරය", "තාලම්පට සහ හොරණෑව", "තම්මැට්ටමට කඩිප්පු දෙකක්ද දවුලට එක් කඩිප්පුවක්ද භාවිත කෙරේ."),
        q("ගැටබෙරයේ දෙපස වාදනය කිරීමේදී නිකුත් වන 'තත්', 'ජිත්', 'තොං', 'නං' යන නාද හඳුන්වන්නේ කුමන නමකින්ද?", "බෙරයේ මූලික ශුද්ධ අක්ෂර (මූලික බීජාක්ෂර)", "සිංහල ස්වර හෝඩිය", "බටහිර ස්වර පුවරුව", "තාලම් තිත්", "මෙම සතර අක්ෂර එක්වීමෙන් සංකීර්ණ උඩරට බෙර පද මාලා ගොඩනැගේ."),
        q("පහතරට 'යක් බෙරය' වාදනය කිරීමේදී නැඟෙන ප්‍රධාන බීජාක්ෂර කිහිපයක් මොනවාද?", "දොං, ජිං, තක, තරි, කිට, කුඳ", "ස, රි, ග, ම", "ක, ඛ, ග, ඝ", "ආ, ඇ, ඈ, ඉ", "පහතරට යක් බෙරයේ ප්‍රබල නාද සංකලනයන් මෙම අක්ෂරවලින් ප්‍රකට කෙරේ."),
        q("සම්ප්‍රදායික බෙර වාදනයේදී 'තාලම' වැරදී යාම වැළැක්වීම සඳහා වාදකයන් භාවිත කරන අභ්‍යන්තර මිනුම කුමක්ද?", "මාත්‍රා ගණනය හා ලය පවත්වා ගැනීම", "ඔරලෝසුව දෙස බලා සිටීම", "ගණන් පොතක් බැලීම", "අනෙක් අයට කතා කිරීම", "සංගීත රිද්ම හැඟීම හා පුහුණුව මගින් නිවැරදිව ලය රඳවා ගනී."),
        q("ශ්‍රී ලංකාවේ නර්තන වාද්‍ය භාණ්ඩ කලාව සංරක්ෂණය කිරීම සඳහා පාසල් මට්ටමින් කළ හැකි වඩාත් සුදුසු දෙය කුමක්ද?", "සාම්ප්‍රදායික වාද්‍ය භාණ්ඩ හඳුනාගෙන වැයීමට හුරු වීම", "සියලු දේශීය බෙර වෙනුවට බටහිර සංගීත භාණ්ඩ යෙදීම", "ශාන්තිකර්ම බෙර වාදනය පාසල්වලින් ඉවත් කිරීම", "හස්ත මුද්‍රා පමණක් පුහුණු වී වාදනය අත්හැරීම", "අපේ දේශීය වාද්‍ය උරුමය රැකීමට ප්‍රායෝගික අධ්‍යයනය ඉතා වැදගත් වේ."),
        q("පංචතූර්ය නාද වර්ගීකරණයේදී 'ඝන' ගණයට උදාහරණ වන වාද්‍ය භාණ්ඩ යුගලයක් තෝරන්න.", "තාලම්පට සහ පන්තේරුව", "ගැටබෙරය සහ යක් බෙරය", "හොරණෑව සහ හක්ගෙඩිය", "දවුල සහ තම්මැට්ටම", "ලෝහ හෝ ලී එකිනෙක ගැටීමෙන් ශබ්ද උපදවන භාණ්ඩ ඝන ගණයට අයත් වේ."),
        q("පංචතූර්ය නාද වර්ගීකරණයේදී 'සුසිර' ගණයට අයත් වන සාම්ප්‍රදායික වාද්‍ය භාණ්ඩ දෙකක් තෝරන්න.", "හොරණෑව සහ කොම්බුව", "තාලම්පට සහ මිණි ගෙඩිය", "උඩැක්කිය සහ රබාන", "දවුල සහ ගැටබෙරය", "වාතය පිඹීමෙන් නාද නිපදවන භාණ්ඩ සුසිර වාද්‍ය ගණයට ගැනේ."),
        q("උඩරට 'ගැටබෙරය' වාදනය කරන විට වාදකයා තම වම් අතින් සහ දකුණු අතින් ගසන ස්ථාන මොනවාද?", "වම් අතින් හරක් සමටත් දකුණු අතින් වඳුරු සමටත් පහර දීම", "දෙඅතින්ම වඳුරු සමට ගැසීම", "දෙඅතින්ම ලී කඳට ගැසීම", "කඩිප්පු දෙකකින් ගැසීම", "දෙපස ඇස් දෙකේ වෙනස් නාදයන් මුසු කිරීමෙන් ගැටබෙර වාදනය සම්පූර්ණ වේ."),
        q("ගැටබෙරයේ බඳෙහි ඇතුළත පෘෂ්ඨය සකස් කරන්නේ කෙසේද?", "සුමටව හාරා මැද කොටසේ අනුනාදය ඇති වන සේ නිමවා", "පස්වලින් සම්පූර්ණයෙන් පුරවා", "යකඩ තහඩු ඔබා", "රෙදි ඔබා", "කුහරයේ හැඩය නිවැරදි නොවුවහොත් බෙරයෙන් මිහිරි නාදයක් නොලැබේ."),
        q("පහතරට 'යක් බෙරය' සඳහා භාවිත කරන 'සම' සකස් කිරීමේදී ගව ආමාශ පටලය (බොකු සම) යොදාගන්නේ ඇයි?", "තුනී බව හා විශේෂිත ගැඹුරු දෝංකාර නාදයක් ලබා දෙන බැවින්", "ඉතා ඝන හා දැඩි මතුපිටක් ඇති කර ගැනීමට", "කොළ පැහැති ස්වාභාවික වර්ණයක් ලබා ගැනීමට", "වාදනයේදී හම පහසුවෙන් ඉරී යාමට හැකි වීමට", "යක් බෙරයේ ආවේණික නාද ගුණය රඳා පවතින්නේ මෙම සම් සැකසුම මතය."),
        q("සබරගමු 'දිගු දවුලේ' ඇස් දෙක අතර දිග ප්‍රමාණය ගැටබෙරයට වඩා කෙබඳු වේද?", "ගැටබෙරයට වඩා තරමක් දිගින් හා මහතින් වැඩිය", "උඩැක්කියට වඩා කුඩාය", "කුඩා පන්තේරුවක් තරම්ය", "අඟල් තුනක් පමණි", "විශාල බඳ හේතුවෙන් සබරගමු දවුල ඈතට ඇසෙන ගාම්භීර හඬක් උපදවයි."),
        q("'තම්මැට්ටම' සාදන ලද මැටි හෝ ලී බඳුන් දෙකෙහි හැඩය සමාන වන්නේ කුමකටද?", "විශාල කෝප්ප හෝ මුට්ටි දෙකක හැඩයට", "දිගු බටයක හැඩයට", "හතරැස් පෙට්ටියක හැඩයට", "තැටියක හැඩයට", "එකට බැඳි බඳුන් දෙක උඩු අතට හරවා මතුපිට සම් ගසා ඇත."),
        q("'උඩැක්කිය' වාදනය කිරීමේදී නැට්ටුවා හෝ වාදකයා විසින් කුඩා මිහිරි හඬක් ලබා ගැනීමට කරන්නේ කුමක්ද?", "දකුණු අතේ ඇඟිලිවලින් මෘදුව හා වේගයෙන් ඇසට තට්ටු කිරීම", "වේගයෙන් බිම ගැසීම", "කඩිප්පු දෙකකින් ගැසීම", "මුවින් පිඹීම", "උඩැක්කි කවි ගයමින් සෞම්‍ය නාද රටා මැවීම උඩරට උත්සවවල අලංකාර අංගයකි."),
        q("'බුම්මැඩිය' වාද්‍ය භාණ්ඩය නිමැවීමේදී මැටි බඳ කැඩී යාම වැළැක්වීමට යොදන ආරක්ෂක පිළිවෙත කුමක්ද?", "පිළිස්සූ මැටි බඳක් ගෙන ලණුවලින් එල්ලා ගැනීම", "බිම දමා පෙරළමින් රිද්ම නාද උපදවා ගැනීම", "කඩිප්පු දෙකකින් මැටි බඳට තදින් පහර දීම", "නොපිලිස්සූ අමු මැටියෙන්ම බඳ සකසා තැබීම", "පැරණි ගැමි කුඹල් කර්මාන්තයේ නිපුණත්වය බුම්මැඩියෙන් පෙනේ."),
        q("'අත් රබාන' වාදනය කිරීමේදී වම් අතේ මහපටැඟිල්ල සහ ඇඟිලිවල කාර්යය කුමක්ද?", "රබාන සමබරව අල්ලාගෙන කරකැවීම සහ රඳවා ගැනීම", "රබාන බිම තැබීම", "පිඹීම", "කඩිප්පුව ඇල්ලීම", "දකුණු අතින් තාලයට ගසන විට වම් අත රබාන හසුරුවයි."),
        q("'බංකු රබානේ' රාමුව මත සම සවි කිරීමට පෙර සම සකස් කරන්නේ කෙසේද?", "හොඳින් පදම් කර තෙත් කර ඇද ගැනීමට හැකි වන සේ සකසා", "අමු සම කෙලින්ම තබා", "ප්ලාස්ටික් ඔතා", "ලුණු නොදමා තබා", "පදම් කළ සම තදින් ගැසීමෙන් වසර ගණනාවක් හොඳ හඬක් රැක ගත හැකිය."),
        q("'හොරණෑව' වාදනය කිරීමේදී විවිධ ස්වර හා තනු උපදවා ගන්නේ කෙසේද?", "ලී නළාවේ සිදුරු ඇඟිලිවලින් වසමින් හා හරිමින්", "පිත්තල කෝණය බඳෙන් ගලවා ඉවත් කිරීමෙන්", "තල්පත් පීප්පය මැදින් කපා ඉවත් කිරීමෙන්", "ලී බඳ මත කඩිප්පුවකින් තට්ටු කිරීමෙන්", "සිංහල ගීත තනු හා ස්වර මාලා හොරණෑවෙන් ඉතා මිහිරිව වාදනය කළ හැකිය."),
        q("'හක්ගෙඩිය' පිඹීම සඳහා එහි කුමන කොටස සිදුරු කර සකසා ඇත්ද?", "හක්ගෙඩියේ සර්පිලාකාර උල් කෙළවර (අග කොටස)", "පළල් විවරය මැද", "පැති බඳ", "අඩියේ කොටස", "කුඩා සිදුරට තොල් තබා වේගයෙන් වාතය පිඹීමෙන් නාදය නිපදවයි."),
        q("'කොම්බුව' පිඹීමේදී හඬ උපදවා ගැනීම සඳහා වාදකයා කළ යුත්තේ කුමක්ද?", "සිහින් කෙළවරේ තොල් තද කර කම්පනය කරමින් සුළං පිඹීම", "තල් කොළ පීප්පයක් දැමීම", "අතින් තට්ටු කිරීම", "සිදුරු හතක් වැසීම", "තඹ හෝ පිත්තල නළාවේ පිඹින ආකාරයෙන් ගාම්භීර හඬක් නැඟේ."),
        q("තාලම්පට යුගලයේ තැටි දෙක සාමාන්‍යයෙන් පවතින ප්‍රමාණය කෙබඳුද?", "අල්ලට සරිලන කුඩා ප්‍රමාණයේ ඝන ලෝහ තැටි දෙකකි", "විශාල රිය සකක් තරම් වේ", "මිලිමීටරයක් තරම් කුඩාය", "මැටි පිඟන් තරම් පැතලිය", "තැටි දෙකේ ඝනකම වැඩි වන තරමට එහි නාදය පැහැදිලි හා දීප්තිමත් වේ."),
        q("පහතරට නැටුමේදී ශිල්පීන් පාදවල පළඳින 'සිළම්බු' නිසා නැටුමට ලැබෙන ප්‍රයෝජනය කුමක්ද?", "පාද චලනවල රිද්ම නිරවද්‍යතාව ශ්‍රව්‍යව ඉස්මතු වීම", "නැට්ටුවාගේ පාදවල බර අඩු කර පැනීමට උපකාරී වීම", "වේදිකාව මත අලංකාර රටා සීරීමට හැකි වීම", "සම් බෙර වාදනය සම්පූර්ණයෙන්ම අනවශ්‍ය වීම", "පාදය තබන සෑම මාත්‍රාවක්ම සිළම්බු හඬින් පැහැදිලි වේ."),
        q("'පන්තේරුව' වාද්‍ය භාණ්ඩය නිර්මාණය වී ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "පිත්තල ලෝහයෙන් සැකසූ වටකුරු රාමුවකි", "උණ බට වළල්ලකි", "ප්ලාස්ටික් තැටියකි", "ගල් වළල්ලකි", "කුඩා රවුම් රාමුවේ සවි කළ පිත්තල පෙති ගැටීමෙන් ඝන නාදය උපදී."),
        q("උඩරට හා පහතරට සම්ප්‍රදායික බෙරවල 'කුරලය' හෙවත් දාර බැම්ම ශක්තිමත් කිරීමට ගන්නා වැල් වර්ගය කුමක්ද?", "වෙණිවැල් හෝ වේවැල්", "කෙසෙල් නූල්", "තණකොළ", "රබර් පටි", "වරපටි අදින විට හම නොඉරී තබා ගැනීමට කුරලය ශක්තිමත්ව වියනු ලැබේ."),
        q("ගැටබෙරයේ 'මන්ද නාද' සහ 'තියුණු නාද' අතර වෙනස පෙන්වන අක්ෂර යුගලක් කුමක්ද?", "දොං (බර) සහ තත් හෝ ජිත් (තියුණු)", "තාල සහ ලය", "ස සහ රි", "රස සහ භාව", "වම් අතේ නාද බර වන අතර දකුණු අතේ නාද තියුණු වේ."),
        q("සබරගමු 'හේවිසි' කට්ටලයට අයත් තම්මැට්ටම සහ දවුල අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "තම්මැට්ටම කඩිප්පු දෙකෙන්ද දවුල අත හා කඩිප්පුවෙන්ද වැයීම", "භාණ්ඩ දෙකම තනි අතින් එකම අයුරින් වැයීම", "සබරගමු දවුල මුවින් පිඹින සුසිර භාණ්ඩයක් වීම", "තම්මැට්ටම පිත්තල තැටි දෙකකින් සාදා තිබීම", "භාණ්ඩ දෙකේ ව්‍යුහය හා වාදන විධිය පැහැදිලිව වෙනස් වේ."),
        q("දේශීය නර්තන වාද්‍ය භාණ්ඩ අතර 'කළගෙඩි' වැනි භාණ්ඩ හඳුන්වනු ලබන්නේ කුමන ආකාරයෙන්ද?", "ගැමි ජන නර්තන හා තාල උපකරණ ලෙස", "රාජකීය සුසිර යුද භාණ්ඩ ලෙස", "බටහිර සංගීත භාණ්ඩ ලෙස", "තන්තු භාණ්ඩ ලෙස", "එදිනෙදා ගෘහ භාණ්ඩ කලාත්මකව භාවිත කිරීම ගැමි නිර්මාණශීලීත්වයයි."),
        q("'මිණි ගෙඩිය' (අත් මිණිය) වාදනය කරන පුද්ගලයා එය අල්ලා ගන්නේ කුමන කොටසින්ද?", "ඉහළින් සවි කර ඇති පිත්තල මිටෙන්", "ඇතුළත දිවෙන්", "පහළ විවෘත දාරයෙන්", "නූලකින් එල්ලාගෙන", "සීනුවේ කම්පනයට බාධා නොවන සේ මිටෙන් අල්ලා සොලවනු ලැබේ."),
        q("පංචතූර්ය වර්ගීකරණයේ 'තත' භාණ්ඩ දේශීය ශාන්තිකර්මවල බහුලව භාවිත නොවීමට හේතුව කුමක්ද?", "එළිමහන් යාග සඳහා ඈතට ඇසෙන බෙර හඬ උචිත වීම", "තන්තු භාණ්ඩ සෑදීමේ ක්‍රම නොදැන සිටි බැවින්", "විදේශීය ආක්‍රමණ හා නීතිමය තහනම් පැවති බැවින්", "අවශ්‍ය දැව වර්ග මෙරට වනාන්තරවල නොතිබූ බැවින්", "ශාන්තිකර්ම හා පෙරහැරවලදී බෙර හා හේවිසි හඬ මූලික කාර්යය ඉටු කරයි."),
        q("උඩැක්කිය වාදනය කිරීමේදී නැට්ටුවා 'දකුණු ඇසට' ගසන ගමන්ම 'මැද රෙදි පටිය' තද කරන්නේ ඇයි?", "ස්වරය ඉහළ පහළ යවා තනුවක මිහිරක් ලබා ගැනීමට", "උඩැක්කිය කැඩීමට", "හඬ සම්පූර්ණයෙන් නැවැත්වීමට", "ඇඟිලි රත් කිරීමට", "තනි බෙරයකින් විවිධ නාද මට්ටම් ලබා ගැනීමට උඩැක්කියේ මෙම තාක්ෂණය උපකාරී වේ."),
        q("ශ්‍රී ලංකාවේ බෙර සාදන පාරම්පරික ශිල්පීන් 'හරක් සම' හා 'එළු සම' පදම් කිරීම සඳහා භාවිත කරන්නේ මොනවාද?", "අළු, හුණු හා ස්වාභාවික ශාක පොතු යොදා සෝදා වියළා ගැනීම", "කෘත්‍රිම ප්ලාස්ටික් තීන්ත වර්ග ආලේප කිරීම", "සිමෙන්ති මිශ්‍ර කළ ජලයේ ගිල්වා තැබීම", "ඛනිජ තෙල් වර්ග ඉස අව්වේ වියළා ගැනීම", "ස්වාභාවික පදම් කිරීම මගින් සමේ ශක්තිමත් බව හා නාද ගුණය රැකේ."),
        q("'රබාන' වාදනය කිරීමේදී රබන් පද අතර හමුවන 'වාරුම්' යනු කුමක්ද?", "තාලයට අනුකූලව රබන් පද ගයමින් කරන රිද්මයානුකූල වාදන රටා", "රබාන අලුත්වැඩියා කිරීම", "රබාන ගින්නේ පිළිස්සීම", "රබන් රාමුව කැපීම", "උත්සවශ්‍රීයෙන් යුතුව ගැයෙන රබන් පද ජන සංගීතයේ අනන්‍ය අංගයකි."),
        q("'පහතරට යක් බෙරයේ' වරපටි ගණන හා සවි කිරීම සකස් කර ඇත්තේ කෙසේද?", "බෙර බඳ වටා සමාන දුරකින් ඇස් දෙකේ කුරල තද කරමින්", "එක් පැත්තක පමණක් ගැට ගසා", "කඳ ඇතුළතින් දමා", "වරපටි නොමැතිව මැලියම් ගා", "සමාන ආතතියක් පවත්වා ගැනීම බෙරයේ නිවැරදි නාදයට අත්‍යවශ්‍ය වේ."),
        q("හේවිසි වාදනයේදී 'පූජා හේවිසි' සහ 'ගමන් හේවිසි' අතර වෙනස කුමක්ද?", "පන්සලේදී හා පෙරහැරේදී වයන පද රටා වෙනස් වීම", "භාවිත කරන තූර්ය භාණ්ඩ වර්ග සම්පූර්ණයෙන්ම වෙනස් වීම", "ගමන් හේවිසිවලදී හොරණෑව සම්පූර්ණයෙන්ම ඉවත් කර තැබීම", "දවුල හා තම්මැට්ටම වෙනුවට තන්තු භාණ්ඩ පමණක් ගැනීම", "සෑම අවස්ථාවකටම ගැළපෙන වෙනම හේවිසි පද මාලා සම්ප්‍රදායේ පවතී."),
        q("දේශීය නර්තන වාද්‍ය භාණ්ඩ අතර 'ගෙජ්ජි' පැළඳීමේදී ඒවා ශබ්ද වන ආකාරය පාලනය කරන්නේ කවුද?", "නැට්ටුවාගේ පාද පියවරවල ශක්තිය හා ලය නිරවද්‍යතාව මගින්", "වේදිකා කළමනාකරු මගින්", "බෙර වාදකයා මගින්", "හොරණෑ වාදකයා මගින්", "නැට්ටුවා අනවශ්‍ය ලෙස පාද සෙලවුවහොත් ගෙජ්ජි හඬින් තාල දෝෂ පැහැදිලිව ඇසේ."),
        q("වාද්‍ය භාණ්ඩයක් වන 'හක්ගෙඩිය' සාමාන්‍යයෙන් දක්ෂිණාවර්ත හා වාමාවර්ත ලෙස බෙදෙන්නේ කුමක් අනුවද?", "හක්ගෙඩියේ ඇතුළත සර්පිලය කරකැවෙන දිශාව අනුව", "හක්ගෙඩියේ සමස්ත බර හා ඝනකම අනුව", "හක්ගෙඩියේ පිටත කවචයේ වර්ණ පැහැය අනුව", "හක්ගෙඩියේ මුඛයේ සිට කෙළවර දිග අනුව", "දක්ෂිණාවර්ත හක්ගෙඩිය ඉතා දුර්ලභ හා අතිශය ශුභ වස්තුවක් ලෙස සැලකේ."),
        q("'කොම්බුව' සහ 'හොරණෑව' යන සුසිර වාද්‍ය භාණ්ඩ දෙක අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "හොරණෑවේ ස්වර සිදුරු හා තල්පත් පීප්පයක් ඇති අතර කොම්බුවේ සිදුරු නැත", "කොම්බුව මුවින් නොපිඹ අතින් ගසා වාදනය කරන බැවින් එය වෙනස් වේ", "හොරණෑව සම්පූර්ණයෙන්ම පිත්තලවලින් සාදා ඇති බැවින් ස්වර නොනැගේ", "කොම්බුව හා හොරණෑව යන දෙකම සුසිර නොවන ඝන වාද්‍ය භාණ්ඩ වේ", "හොරණෑවෙන් තනු වැයිය හැකි අතර කොම්බුවෙන් ගාම්භීර සංඥා නාද දෙයි."),
        q("නර්තන වාද්‍ය භාණ්ඩවල 'කුඩා සිළම්බු' සහ 'විශාල සිළම්බු' භාවිතයේ වෙනස කුමක්ද?", "ප්‍රමාණය හා ලෝහ ඝනකම අනුව සියුම් හෝ ගැඹුරු හඬ ලැබීම", "කුඩා සිළම්බු හිස් පැළඳුමේත් විශාල සිළම්බු ඉණේත් පැළඳීම", "විශාල සිළම්බු ගැටබෙරයේ වරපටියේ එල්ලා තැබීම", "කුඩා සිළම්බු දවුල් කඩිප්පුවේ දෙකෙළවර බැඳීම", "සම්ප්‍රදාය හා නැටුම් අංගය අනුව සිළම්බු ප්‍රමාණය තෝරා ගනී."),
        q("ගැටබෙරයේ බඳ මැදින් පළල් වී තිබීමෙන් එම බෙරයට ලැබෙන නාමය හා පෙනුම කුමක්ද?", "ගැටයක් වැනි මැද කොටස නිසා 'ගැටබෙරය' යන නම ලැබී ඇත", "කළගෙඩි බෙරය යන නම ලැබී ඇත", "පෙට්ටි බෙරය යන නම ලැබී ඇත", "වළලු බෙරය යන නම ලැබී ඇත", "උඩරට සම්ප්‍රදායේ උසස්ම සංකේතයක් ලෙස ගැටබෙරය හැඳින්වේ."),
        q("සබරගමු 'දිගු දවුල' කඩිප්පුවකින් පහර දෙන විට කඩිප්පුව අල්ලා ගන්නා නිවැරදි ආකාරය කුමක්ද?", "මැණික් කටුව නම්‍යශීලීව තබා ඇඟිලිවලින් සමබරව අල්ලා ගැනීම", "දෙඅතින්ම තදින් අල්ලා උරහිසට ගැනීම", "වැලමිටෙන් තද කිරීම", "මිට මොළවා සම ඉරෙන සේ ගැසීම", "සැහැල්ලු මැණික් කටු චලනය වේගවත් දවුල් රෝල් වැයීමට උපකාරී වේ."),
        q("තම්මැට්ටම වාදනය කිරීමේදී වාදකයාට ඉක්මන් ත්‍රීව්‍ර රිද්ම (රෝල්) ලබා ගැනීමට හැකි වන්නේ ඇයි?", "කඩිප්පු දෙකක් මාරුවෙන් මාරුවට වේගයෙන් ගැසිය හැකි බැවින්", "තනි අතේ ඇඟිලිවලින් පමණක් තට්ටු කර වයන බැවින්", "මුවින් හුළං පිඹිමින් සුසිර නාදයක් උපදවන බැවින්", "ලෝහ තන්තු කම්පනය කිරීමෙන් තාල නාද මවන බැවින්", "පෙරහැර හා හේවිසි වාදනයේදී තම්මැට්ටමේ අඛණ්ඩ රෝල් නාදය ඉතා ප්‍රසිද්ධය."),
        q("'බුම්මැඩිය' සෑදීමේදී තලගොයි සමක් වෙනුවට අද වන විට බහුලව භාවිත කරන විකල්ප සම කුමක්ද?", "තුනී එළු සම", "මී හරක් සම", "අලි සම", "ප්ලාස්ටික් බෑග්", "වන සතුන් ආරක්ෂා කිරීම හා පහසුව නිසා එළු සම බහුලව යොදා ගනී."),
        q("දේශීය වාද්‍ය භාණ්ඩයක් වන 'ගෙජ්ජි' වළලුකරේ බඳින විට නැට්ටුවා පරීක්ෂා කළ යුත්තේ කුමක්ද?", "පාදයට තද නොවී හෝ ගැලවී නොයන සේ නිවැරදිව බැඳ ඇතිද යන්න", "ගෙජ්ජිවල ලෝහ ඇට ඉවත් කර ශබ්දය සම්පූර්ණයෙන් නැතිද යන්න", "නැට්ටුවාගේ වෙස් තට්ටුව හා උරමාලය ගැලපෙන පැහැයෙන් ඇතිද යන්න", "බෙර වාදකයාගේ තාලම්පට තැටි දෙක නිසි ලෙස ගැටගසා ඇතිද යන්න", "වේදිකාව මත ආරක්ෂිතව හා පහසුවෙන් නැටීමට ගෙජ්ජි නිසි ලෙස බැඳීම වැදගත් වේ."),
        q("'පන්තේරු නැටුම' සඳහා පන්තේරුව අතින් කරකවන අතරතුර එයින් 'තාල' අල්ලන්නේ කෙසේද?", "වෙනත් අතක ඇඟිලිවලින් හෝ ශරීරයෙන් වද්දමින් පිත්තල පෙති සෙලවීමෙන්", "පන්තේරුව බිම දමා පාදයෙන් තදින් පෑගීමෙන්", "වළල්ල මුවට තබා සුළං පිඹීමෙන් ශබ්දය ඉපදවීමෙන්", "සබරගමු දවුල් කඩිප්පුවකින් මැදට ගැසීමෙන්", "නැටුම් හරඹය හා තාල වාදනය එකවර සිදුවීම පන්තේරුවේ අපූර්වත්වයයි."),
        q("ශ්‍රී ලංකාවේ දේශීය වාද්‍ය භාණ්ඩ හා ඉන්දියානු 'තබ්ලාව' අතර ඇති පොදු ලක්ෂණය කුමක්ද?", "සම් භාවිත කර අතින් වයන අවනද්ධ හෙවත් ආතත වාද්‍ය භාණ්ඩ වීම", "දෙකම මුවින් පිඹ වාදනය කරන සුසිර වාද්‍ය භාණ්ඩ වීම", "දෙකම ලෝහ තැටි ගැටීමෙන් වයන ඝන වාද්‍ය භාණ්ඩ වීම", "දෙකම තන්තු කම්පනය කර වයන තත වාද්‍ය භාණ්ඩ වීම", "පෙරදිග තාල වාද්‍ය සංස්කෘතිය තුළ මෙම භාණ්ඩ එකම කාණ්ඩයට අයත් වේ."),
        q("නර්තන වාද්‍ය භාණ්ඩවල 'නඩත්තුව' සඳහා වරපටිවලට ස්වාභාවික තෙල් ස්වල්පයක් ආලේප කරන්නේ ඇයි?", "හම් වියළී ඉරිතැලීම වළක්වා නම්‍යශීලී බව රැක ගැනීමට", "වාදනය අතරතුර හම ලිස්සා බුරුල් වී යාමට සැලැස්වීමට", "බෙරයේ සමස්ත බර ප්‍රමාණය ඉහළ නංවා ගැනීමට", "හමේ ස්වාභාවික වර්ණය තද කළු පැහැයට හැරවීමට", "නිසි නඩත්තුව මඟින් වටිනා දේශීය බෙර දීර්ඝ කාලයක් ආරක්ෂා කර ගත හැකිය."),
        q("උඩරට බෙර පද මාලාවේ හමුවන 'තකිට' යන නාදය අයත් වන්නේ මාත්‍රා කීයක ඒකකයකටද?", "මාත්‍රා තුනක (තිස්‍ර) ඒකකයකට", "මාත්‍රා හතරක ඒකකයකට", "මාත්‍රා හයක ඒකකයකට", "මාත්‍රා දහයක ඒකකයකට", "ත-කි-ට යන අක්ෂර තුන තාල ගණනයේ මූලික ඒකකයකි."),
        q("සිංහල සංස්කෘතියේ 'මළ බෙර' හෙවත් අවමංගල්‍ය අවස්ථාවලදී වයන දවුල හෝ බෙරය සකසන්නේ කෙසේද?", "වරපටි මඳක් බුරුල් කර ශෝකී ගැඹුරු හඬක් ලැබෙන පරිදි", "හොරණෑව සමඟ ප්‍රීතිමත් තනු වයමින්", "පන්තේරුව කරකවමින්", "තාලම්පට වේගයෙන් ගසමින්", "අවස්ථාවේ ශෝකී ගෞරවය රැකෙන පරිදි නාදය හා ලය වෙනස් කර වයනු ලැබේ."),
        q("'බටනලාව' නිපදවීමේදී එහි හඬ පැහැදිලි වීමට උණ බටය ඇතුළත සකස් කරන්නේ කෙසේද?", "ඇතුළත ගැට සහ කෙඳි සුමට ලෙස ඉවත් කර පිරිසිදු කිරීමෙන්", "පස් පුරවා තැබීමෙන්", "රෙදි ඔබා තැබීමෙන්", "ලී කැබලි සිර කිරීමෙන්", "සුමට වායු කුහරය ස්වර පැහැදිලිව නැඟීමට අත්‍යවශ්‍ය වේ."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතරින් 'රබන්' වර්ග දෙකක් නම් කරන්න.", "අත් රබාන සහ බංකු රබාන", "ගැට රබාන සහ තම් රබාන", "ලෝහ රබාන සහ වීදුරු රබාන", "දිගු රබාන සහ කොට රබාන", "ප්‍රමාණය හා වාදන ක්‍රමය අනුව අත් රබාන හා බංකු රබාන ලෙස බෙදේ."),
        q("පංචතූර්ය නාද වර්ගීකරණයේදී 'තාලම්පට' වැනි භාණ්ඩ 'ඝන' ලෙස නම් කිරීමට හේතු වූ භෞතික ලක්ෂණය කුමක්ද?", "සම් හෝ සුළං නොමැතිව ඝන ද්‍රව්‍ය එකට ගැටීමෙන් ශබ්දය ඉපදීම", "ලෝහ තැටි ප්‍රමාණයෙන් විශාල හා බරින් වැඩි වීම නිසා පමණි", "දිගු කාලයක් භාවිත කිරීමේදී තද කළු පැහැයක් ගන්නා නිසා", "ඝන ලෝහ මිශ්‍රණය ජලය මත පාවීමේ හැකියාවක් නොමැති නිසා", "නාද උත්පාදන මාධ්‍යය අනුව මෙම නාමකරණය සිදු කර ඇත."),
        q("ගැටබෙරයේ 'වඳුරු සම' (දකුණු ඇස) වෙනුවට අද වන විට ඇතැම් විට වෙනත් තුනී සම් යොදන්නේ ඇයි?", "පරිසර හා වනජීවී සංරක්ෂණ නීති නිසා හා සුලබ බව නිසා", "හඬ නැති කිරීමට", "බර වැඩි කිරීමට", "පැහැය වෙනස් කිරීමට", "සදාචාරාත්මක හා පාරිසරික හේතු මත විකල්ප සම් භාවිතය ප්‍රවර්ධනය වී ඇත."),
        q("දේශීය නර්තන වාද්‍ය භාණ්ඩයක 'හඬ නැංවීමේ' ක්‍රියාවලිය සඳහා ප්‍රධානතම භෞතික සංසිද්ධිය කුමක්ද?", "සම, තන්තු, ලෝහ තැටි හෝ වායු කඳ කම්පනය වීම", "ආලෝක පරාවර්තනය", "විදුලි ධාරාව ගැලීම", "චුම්බක ආකර්ෂණය", "ඕනෑම සංගීත භාණ්ඩයක ශබ්දය උපදින්නේ කම්පනය මගිනි."),
        q("උඩරට වන්නම් 18 වාදනය කිරීමේදී ප්‍රධාන වශයෙන් යොදාගන්නා බෙර යුගලය හෝ භාණ්ඩ යුගලය කුමක්ද?", "ගැටබෙරය සහ තාලම්පට", "යක් බෙරය සහ කයිතාලම", "දවුල සහ කළගෙඩිය", "බටනලාව සහ වයලීනය", "ගැටබෙර පද හා තාලම්පට තිත එක්ව වන්නම් කවිවලට ජීවය දෙයි."),
        q("වත්මන් ශ්‍රී ලංකාවේ සාම්ප්‍රදායික වාද්‍ය භාණ්ඩ නිෂ්පාදන කර්මාන්තය රැකගැනීමට කළ හැකි හොඳම පියවර කුමක්ද?", "පාරම්පරික බෙර නිපදවන ශිල්පීන්ට අතහිත දීම හා ගුණාත්මක භාණ්ඩ අගය කිරීම", "සියලු බෙර ආනයනය කිරීම", "ප්ලාස්ටික් සෙල්ලම් බෙර පමණක් ගැනීම", "බෙර වාදනය පාසල්වලින් ඉවත් කිරීම", "හස්ත කර්මාන්තයක් ලෙස දේශීය වාද්‍ය භාණ්ඩ නිමැවුම අපේ සංස්කෘතික ආර්ථිකයේ කොටසකි.")
    )
}
